; sixth.asm -- chapter 37: the tune with one frame in six left out at 60 Hz
; generated by gen37.py
        INCLUDE "msx.inc"
        OUTPUT "sixth.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
ticks   EQU VARS                ; the player's ticks, two bytes
owed    EQU VARS + 2            ; lines owed to the player, two bytes
lines   EQU VARS + 4            ; the machine's lines a frame: 313 or 262
tick    EQU VARS + 6            ; ticks still to the next row
step    EQU VARS + 7            ; the song's step, two bytes
barno   EQU VARS + 9            ; the step's number, 1 to 16
rowno   EQU VARS + 10           ; the row in the bar, 0 to 15
frames  EQU VARS + 11           ; frames counted by isr
skip    EQU VARS + 12           ; sixth.asm: frames to the next one left out
seen    EQU VARS + 13           ; latch.asm: the frame read in
port1   EQU VARS + 14           ; latch.asm: register 14 of port 1
nextrq  EQU VARS + 15           ; effects.asm: the next request, two bytes
saidp   EQU VARS + 17           ; and where its answer goes, two bytes
said    EQU VARS + 19           ; the answers: 0 taken, $FF refused
shadow  EQU VARS + $20          ; R0 to R10, as the next tick sends them
chan_a  EQU shadow + 11         ; the channels, CHAN bytes each
chan_b  EQU chan_a + CHAN
chan_c  EQU chan_b + CHAN
chan_x  EQU chan_c + CHAN       ; the effect: a fourth channel, on C's registers
WAITS   EQU 0                   ; rows to wait; an effect: ticks to sound
NOTE    EQU 1                   ; the note, 0 for a rest
INSTR   EQU 2                   ; the instrument
PATTERN EQU 3                   ; the next event
VOLUME  EQU 5                   ; this tick's level in the volume table
PITCHES EQU 7                   ; this tick's semitones
FIRST   EQU 9                   ; the pitch table's first byte
MIXER   EQU 11                  ; the instrument's TONE and NOISE
NOISEP  EQU 12                  ; its noise's period
SHPER   EQU 13                  ; where in shadow its period goes
SHLEV   EQU 15                  ; and its level
TMASK   EQU 17                  ; R7 with its tone bit at 0
NMASK   EQU 18                  ; R7 with its noise bit at 0
PRIO    EQU 19                  ; an effect's priority
CHAN    EQU 20                  ; bytes a channel
IM2_TABLE EQU $C200             ; 257 bytes of $C3: every vector is $C3C3
IM2_JUMP  EQU $C3C3             ; and there, a JP to the routine
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off
        VDP_REG 0, $00          ; Graphic I
        VDP_REG 2, $06          ; names    $1800
        VDP_REG 3, $80          ; colours  $2000
        VDP_REG 4, $00          ; patterns $0000
        VDP_REG 5, $36          ; sprite attributes $1B00
        VDP_REG 6, $07          ; sprite patterns   $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; patterns: chapter 30's set at 32
        ld hl, shapes
        ld e, 4
        call send
        VRAM_WRITE $2000        ; black ink on white paper
        ld a, $1F
        ld b, 32
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; the names
        ld hl, names
        ld e, 3
        call send
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld a, ($002B)           ; bit 7 is 1 on a 50 Hz machine (chapter 4)
        rla
        ld hl, 262              ; 60 Hz ...
        jr nc, .rlines
        ld hl, 313              ; ... and 50 Hz
.rlines:ld (lines), hl
        ld a, ($002B)           ; and sixth.asm's count: 6 at 60 Hz, 0 at 50
        rla
        ld a, 6
        jr nc, .six
        xor a
.six:   ld (skip), a
        ld hl, 0
        ld (owed), hl
        ld (ticks), hl
        ld a, 1                 ; the first tick reads a row
        ld (tick), a
        xor a
        ld (barno), a
        ld (rowno), a
        ld (frames), a
        ld hl, song - 6         ; the step before the first
        ld (step), hl
        ld hl, start            ; shadow and the four channels
        ld de, shadow
        ld bc, 91
        ldir
        ld hl, IM2_TABLE        ; mode 2: the table, 257 bytes of $C3
        ld de, IM2_TABLE + 1
        ld bc, 256
        ld (hl), high IM2_JUMP
        ldir
        ld a, $C3               ; and at $C3C3, JP isr
        ld (IM2_JUMP), a
        ld hl, isr
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a                 ; I: the page of the table
        im 2
        VDP_REG 1, $E0          ; the display on, and the frame's signal
        in a, (VDP_CTRL)
main:   ei
        halt                    ; wait for the frame
        di                      ; the interrupts off: the VDP, the effects
        call show
        jp main

; isr: every frame. When pace gives the player a tick, last tick's
; registers are sent first, so that every tick's writes land at the same
; T-states after the interrupt, and the next tick is worked out after.
; Keeps every register it uses
isr:    push af                 ; 12
        push bc                 ; 12
        push de                 ; 12
        push hl                 ; 12
        push ix                 ; 17
        in a, (VDP_CTRL)        ; 12  the status: the signal down
        ld hl, frames           ; 11
        inc (hl)                ; 12
        call pace               ; 18  carry: the player's tick
        jr nc, .done            ; 13, or 8
        call tochip             ; 18
        call play               ; 18
.done:  pop ix                  ; 16
        pop hl                  ; 11
        pop de                  ; 11
        pop bc                  ; 11
        pop af                  ; 11
        ei                      ;  5
        ret                     ; 11

; pace: sixth.asm's: at 60 Hz one frame in six left out, none at 50 Hz.
; skip is the frames to the next one left out, 0 on a 50 Hz machine. Uses A
pace:   ld a, (skip)            ; 14
        or a                    ;  5
        scf                     ;  5
        ret z                   ; 12, or 6  50 Hz: every frame
        dec a                   ;  5
        ld (skip), a            ; 14
        scf                     ;  5
        ret nz                  ; 12, or 6
        ld a, 6                 ;  8  the sixth: left out
        ld (skip), a            ; 14
        or a                    ;  5  no carry
        ret                     ; 11

; tochip: R0 to R10 from shadow, in order. Uses A, BC, HL
tochip: ld hl, shadow           ; 11
        ld bc, 11 << 8 | PSG_WRITE ; 11  B: the registers; C: the port
        xor a                   ;  5  R0 first
.reg:   out (PSG_ADDR), a       ; 12  the register
        inc a                   ;  5
        outi                    ; 18  its byte; HL on, and B down
        jr nz, .reg             ; 13, or 8
        ret                     ; 11

; play: the next tick into shadow: every SPEED ticks a row of each channel,
; then each channel's level, period and mixer bits, and an effect, if one
; is sounding, over channel C. Uses A, BC, DE, HL, IX
play:   ld hl, (ticks)          ; 17  one tick more
        inc hl                  ;  7
        ld (ticks), hl          ; 17
        ld hl, tick             ; 11
        dec (hl)                ; 12
        jr nz, .sounds          ; 13, or 8
        ld (hl), SPEED          ; 11  a row
        ld hl, rowno            ; 11
        inc (hl)                ; 12  next sets it to 0 at a new bar
        ld ix, chan_a           ; 16
        call row                ; 18
        ld ix, chan_b           ; 16
        call row                ; 18
        ld ix, chan_c           ; 16
        call row                ; 18
.sounds: ld a, $BF              ;  8  all shut; bit 7 at 1, bit 6 at 0
        ld (shadow + 7), a      ; 14
        ld ix, chan_a           ; 16
        call sound              ; 18
        ld ix, chan_b           ; 16
        call sound              ; 18
        ld ix, chan_c           ; 16
        call sound              ; 18
        ld ix, chan_x           ; 16  an effect?
        ld a, (ix + WAITS)      ; 21  its ticks still to sound
        or a                    ;  5
        ret z                   ; 12, or 6  none: channel C is the music's
        dec (ix + WAITS)        ; 25
        ld a, (shadow + 7)      ; 14  the music's tone and noise on C shut
        or %00100100            ;  8
        ld (shadow + 7), a      ; 14
        jp sound                ; 11  the effect's, whose RET is play's

; row: IX = a channel -> a row: one less to wait, and at none, its pattern's
; next event, and its instrument's tables from their first byte. Uses A,
; BC, DE, HL
row:    dec (ix + WAITS)        ; 25
        ret nz                  ; 12, or 6
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
        cp END                  ;  8  the pattern's end?
        jr nz, .event           ; 13, or 8
        call next               ; 18  the song's next step
        ld a, (hl)              ;  8
        inc hl                  ;  7
.event: bit 7, a                ; 10  an instrument first?
        jr z, .note             ; 13, or 8
        and $7F                 ;  8
        ld (ix + INSTR), a      ; 21
        ld a, (hl)              ;  8
        inc hl                  ;  7
.note:  ld (ix + NOTE), a       ; 21  0 for a rest
        ld a, (hl)              ;  8  the rows it lasts
        inc hl                  ;  7
        ld (ix + WAITS), a      ; 21
        ld (ix + PATTERN), l    ; 21
        ld (ix + PATTERN + 1), h ; 21

; voice: IX = a channel -> its instrument's two tables from their first
; byte, its mixer bits and its noise's period, from instruments, 6 bytes
; each. Leaves the carry clear. Uses A, DE, HL
voice:  ld a, (ix + INSTR)      ; 21
        ld l, a                 ;  5
        add a, a                ;  5
        add a, l                ;  5  three times
        add a, a                ;  5  six times
        ld l, a                 ;  5
        ld h, 0                 ;  8
        ld de, instruments      ; 11
        add hl, de              ; 12  no carry: the table is in the ROM
        ld a, (hl)              ;  8  the volume table
        ld (ix + VOLUME), a     ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + VOLUME + 1), a ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the pitch table
        ld (ix + PITCHES), a    ; 21
        ld (ix + FIRST), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8
        ld (ix + PITCHES + 1), a ; 21
        ld (ix + FIRST + 1), a  ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the mixer's bits
        ld (ix + MIXER), a      ; 21
        inc hl                  ;  7
        ld a, (hl)              ;  8  the noise's period
        ld (ix + NOISEP), a     ; 21
        ret                     ; 11

; next: the song's next step, or its first after the last: each channel's
; new pattern, and IX's in HL; the bar counted, and its row 0. Uses A, BC,
; DE, HL
next:   ld hl, (step)           ; 17
        ld de, 6                ; 11
        add hl, de              ; 12
        ld a, (hl)              ;  8
        inc hl                  ;  7
        or (hl)                 ;  8  a word 0: the end
        dec hl                  ;  7
        ld a, (barno)           ; 14
        jr nz, .keep            ; 13, or 8
        ld hl, song             ; 11  the first step again
        xor a                   ;  5
.keep:  inc a                   ;  5
        ld (barno), a           ; 14
        ld (step), hl           ; 17
        xor a                   ;  5
        ld (rowno), a           ; 14
        ld de, chan_a + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_b + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld de, chan_c + PATTERN ; 11
        ldi                     ; 18
        ldi                     ; 18
        ld l, (ix + PATTERN)    ; 21
        ld h, (ix + PATTERN + 1) ; 21
        ret                     ; 11

; sound: IX = a channel -> its level, and for a note its period, in
; shadow, its tables a tick on; its tone and noise opened in R7, and R6
; its noise's period. Uses A, BC, DE, HL
sound:  ld c, 0                 ;  8  a rest's level
        ld a, (ix + NOTE)       ; 21
        or a                    ;  5
        jr z, .level            ; 13, or 8
        ld l, (ix + VOLUME)     ; 21
        ld h, (ix + VOLUME + 1) ; 21
        ld a, (hl)              ;  8  this tick's level
        cp END                  ;  8  the table's end?
        jr nz, .vstep           ; 13, or 8
        dec hl                  ;  7  the last level again
        ld c, (hl)              ;  8
        jr .pitch               ; 13
.vstep: ld c, a                 ;  5
        inc hl                  ;  7
        ld (ix + VOLUME), l     ; 21
        ld (ix + VOLUME + 1), h ; 21
.pitch: ld l, (ix + PITCHES)    ; 21
        ld h, (ix + PITCHES + 1) ; 21
        ld a, (hl)              ;  8  this tick's semitones
        cp LOOP                 ;  8
        jr nz, .hold            ; 13, or 8
        ld l, (ix + FIRST)      ; 21  the first again
        ld h, (ix + FIRST + 1)  ; 21
        ld a, (hl)              ;  8
        jr .pstep               ; 13
.hold:  cp HOLD                 ;  8
        jr nz, .pstep           ; 13, or 8
        dec hl                  ;  7  the last again
        ld a, (hl)              ;  8
        jr .pnote               ; 13
.pstep: inc hl                  ;  7
        ld (ix + PITCHES), l    ; 21
        ld (ix + PITCHES + 1), h ; 21
.pnote: add a, (ix + NOTE)      ; 21  the note they move it to
        add a, a                ;  5
        ld l, a                 ;  5
        ld h, high notes        ;  8  its period, in a page of its own
        ld e, (hl)              ;  8
        inc l                   ;  5
        ld d, (hl)              ;  8
        ld l, (ix + SHPER)      ; 21
        ld h, (ix + SHPER + 1)  ; 21
        ld (hl), e              ;  8
        inc hl                  ;  7
        ld (hl), d              ;  8
.level: ld l, (ix + SHLEV)      ; 21
        ld h, (ix + SHLEV + 1)  ; 21
        ld (hl), c              ;  8
        ld b, (ix + MIXER)      ; 21
        ld a, (shadow + 7)      ; 14
        bit 0, b                ; 10  a tone?
        jr z, .noise            ; 13, or 8
        and (ix + TMASK)        ; 21
.noise: bit 1, b                ; 10  a noise?
        jr z, .mixer            ; 13, or 8
        and (ix + NMASK)        ; 21
        ld (shadow + 7), a      ; 14
        ld a, (ix + NOISEP)     ; 21
        ld (shadow + 6), a      ; 14
        ret                     ; 11
.mixer: ld (shadow + 7), a      ; 14
        ret                     ; 11

; show: the bar, the row and the ticks, and channel A's, B's and C's levels
; in shadow, as meters and as numbers. Uses A, B, C, D, E
show:   ld d, 3
        ld e, 6
        call at
        ld a, (barno)
        call dec2
        ld e, 15
        call at
        ld a, (rowno)
        call dec2
        ld d, 4
        ld e, 6
        call at
        ld a, (ticks + 1)
        call hex
        ld a, (ticks)
        call hex
        ld d, 6
        ld e, 3
        call at
        ld a, (shadow + 8)
        call meter
        ld e, 19
        call at
        ld a, (shadow + 8)
        call dec2
        ld d, 7
        ld e, 3
        call at
        ld a, (shadow + 9)
        call meter
        ld e, 19
        call at
        ld a, (shadow + 9)
        call dec2
        ld d, 8
        ld e, 3
        call at
        ld a, (shadow + 10)
        call meter
        ld e, 19
        call at
        ld a, (shadow + 10)
        call dec2
        ret

; dec2: A, 0 to 99, as two decimal digits from the address set. Uses A, B, C
dec2:   ld c, -1                ;  8  the tens, counted
.tens:  inc c                   ;  5
        sub 10                  ;  8
        jr nc, .tens            ; 13, or 8
        add a, 10               ;  8  the ones
        ld b, a                 ;  5
        ld a, c                 ;  5
        call .digit             ; 18
        ld a, b                 ;  5
.digit: add a, '0'              ;  8
        out (VDP_DATA), a       ; 12
        ret                     ; 11

; meter: A = a level, 0 to 15 -> fifteen boxes from the address set, as
; many of them filled as the level. Uses A, B, C
meter:  ld c, a                 ;  5
        ld b, 15                ;  8
.cell:  ld a, 2                 ;  8  a filled box ...
        dec c                   ;  5
        jp p, .put              ; 11
        ld a, 1                 ;  8  ... or, past the level, an empty one
.put:   out (VDP_DATA), a       ; 12
        djnz .cell              ; 14, or 9
        ret                     ; 11

; at: the next characters go to row D, column E (chapter 30)
at:     ld a, d
        rrca
        rrca
        rrca
        ld c, a
        and $E0
        or e
        out (VDP_CTRL), a
        ld a, c
        and $03
        or $18 | $40
        out (VDP_CTRL), a
        ret

; cells: A as eight boxes from bit 7, a filled box for a 0 (a key held) and
; an empty one for a 1, from the address set. Uses A, B, L
cells:  ld l, a
        ld b, 8
.cell:  ld a, 2
        rlc l                   ; the next bit, into the carry
        jr nc, .put             ; 0: held
        ld a, 1
.put:   out (VDP_DATA), a
        djnz .cell
        ret

; hex: A as two hexadecimal digits, from the address set. Uses A, C
hex:    ld c, a
        rrca
        rrca
        rrca
        rrca
        call .digit
        ld a, c
.digit: and $0F
        add a, '0'
        cp '9' + 1
        jr c, .out
        add a, 'A' - '9' - 1
.out:   out (VDP_DATA), a
        ret

; send: E blocks of 256 bytes from HL to the VDP
send:   ld c, VDP_DATA
        ld b, 0
.otir:  otir
        dec e
        jr nz, .otir
        ret
start:                          ; shadow, the channels A, B and C, the effect
        db $00, $00, $00, $00, $00, $00, $00, $BF, $00, $00, $00
        db 1, 0, 0              ; A: WAITS, NOTE, INSTR
        dw started, 0, 0, 0     ; PATTERN, VOLUME, PITCHES, FIRST
        db 0, 0                 ; MIXER, NOISEP
        dw shadow + 0, shadow + 8 ; SHPER, SHLEV
        db $FE, $F7, 0          ; TMASK, NMASK, PRIO
        db 1, 0, 0              ; B: WAITS, NOTE, INSTR
        dw started, 0, 0, 0     ; PATTERN, VOLUME, PITCHES, FIRST
        db 0, 0                 ; MIXER, NOISEP
        dw shadow + 2, shadow + 9 ; SHPER, SHLEV
        db $FD, $EF, 0          ; TMASK, NMASK, PRIO
        db 1, 0, 0              ; C: WAITS, NOTE, INSTR
        dw started, 0, 0, 0     ; PATTERN, VOLUME, PITCHES, FIRST
        db 0, 0                 ; MIXER, NOISEP
        dw shadow + 4, shadow + 10 ; SHPER, SHLEV
        db $FB, $DF, 0          ; TMASK, NMASK, PRIO
        db 0, 0, 0              ; X: WAITS, NOTE, INSTR
        dw 0, 0, 0, 0     ; PATTERN, VOLUME, PITCHES, FIRST
        db 0, 0                 ; MIXER, NOISEP
        dw shadow + 4, shadow + 10 ; SHPER, SHLEV
        db $FB, $DF, 0          ; TMASK, NMASK, PRIO
started: db END                 ; a pattern's end: the first row reads the song
        INCLUDE "music.inc"
names:                          ; 24 rows of 32
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $73, $69, $78, $74, $68, $2E, $61, $73, $6D, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $62, $61, $72, $20, $20, $20, $20, $20, $20, $20, $72, $6F, $77, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $74, $69, $63, $6B, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $41, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $42, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $43, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
        db $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20, $20
